function validate([bank]) {
  if (bank.length < 1 || bank.length > 500) return 'bank needs 1 to 500 rows.';
  const n = bank[0].length;
  if (n < 1 || n > 500) return 'Each row has 1 to 500 cells.';
  for (const row of bank) {
    if (row.length !== n) return 'All rows must have the same length.';
    if (!/^[01]*$/.test(row)) return "Rows contain only '0' and '1'.";
  }
  return null;
}

