function numberOfBeams(bank) {
  const spots = [];
  for (let r = 0; r < bank.length; r++)
    for (let c = 0; c < bank[r].length; c++)
      if (bank[r][c] === '1') spots.push(r);
  let beams = 0;
  for (let a = 0; a < spots.length; a++)
    for (let b = 0; b < spots.length; b++) {
      const top = spots[a], bottom = spots[b];
      if (top >= bottom) continue;
      let clear = true;
      for (let r = top + 1; r < bottom; r++) if (bank[r].indexOf('1') !== -1) clear = false;
      if (clear) beams++;
    }
  return beams;
}

