function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 100 : 1 + Math.floor(rand() * 5);
  const n = large ? 100 : 1 + Math.floor(rand() * 5);
  const bank = [];
  for (let r = 0; r < m; r++) {
    const density = rand() < 0.35 ? 0 : rand();
    let row = '';
    for (let c = 0; c < n; c++) row += rand() < density ? '1' : '0';
    bank.push(row);
  }
  return [bank];
}
